create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check(role in ('student','parent','admin')), approved boolean not null default false, student_id text unique, class_name text, section text, photo_url text, created_at timestamptz not null default now());
create table if not exists public.parent_children(parent_id uuid references public.profiles(id) on delete cascade, student_id uuid references public.profiles(id) on delete cascade, primary key(parent_id,student_id));
create table if not exists public.attendance(id bigint generated by default as identity primary key, student_id uuid not null references public.profiles(id) on delete cascade, attendance_date date not null, status text not null check(status in ('present','absent','late')), unique(student_id,attendance_date));
create table if not exists public.exams(id bigint generated by default as identity primary key,name text not null,exam_date date,created_at timestamptz default now());
create table if not exists public.results(id bigint generated by default as identity primary key,student_id uuid not null references public.profiles(id) on delete cascade,exam_id bigint not null references public.exams(id) on delete cascade,subject text not null,obtained numeric not null,total numeric not null,grade text,position integer,published boolean not null default false); 
create table if not exists public.announcements(id bigint generated by default as identity primary key,title text not null,body text not null,published boolean not null default false,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.parent_children enable row level security; alter table public.attendance enable row level security; alter table public.exams enable row level security; alter table public.results enable row level security; alter table public.announcements enable row level security;
create policy "profile self" on public.profiles for select to authenticated using(id=auth.uid());
create policy "parent links" on public.parent_children for select to authenticated using(parent_id=auth.uid());
create policy "attendance own" on public.attendance for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.parent_children pc where pc.parent_id=auth.uid() and pc.student_id=attendance.student_id));
create policy "results own published" on public.results for select to authenticated using(published and (student_id=auth.uid() or exists(select 1 from public.parent_children pc where pc.parent_id=auth.uid() and pc.student_id=results.student_id)));
create policy "exam visible" on public.exams for select to authenticated using(exists(select 1 from public.results r where r.exam_id=exams.id and r.published and (r.student_id=auth.uid() or exists(select 1 from public.parent_children pc where pc.parent_id=auth.uid() and pc.student_id=r.student_id))));
create policy "announcements published" on public.announcements for select to authenticated using(published);